plugins {
    id 'java'
    id 'org.springframework.boot' version '4.1.1'
    id 'io.spring.dependency-management' version '1.1.7'
}

group = 'org.example'
version = '0.0.1-SNAPSHOT'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    // start.spring.io에서 고른 것: Spring Web · Spring Data JPA · Validation · MySQL Driver · Flyway Migration
    implementation 'org.springframework.boot:spring-boot-starter-webmvc'
    implementation 'org.mybatis.spring.boot:mybatis-spring-boot-starter:4.1.0'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-flyway'
    // 10-3 비밀번호 해시(BCrypt) — Spring Security 전체가 아니라 암호화 모듈만
    implementation 'org.springframework.security:spring-security-crypto'
    // 10-4 JWT 발급·검증(jjwt) — api는 컴파일에, 구현·JSON 처리는 실행할 때만
    implementation 'io.jsonwebtoken:jjwt-api:0.13.0'
    runtimeOnly 'io.jsonwebtoken:jjwt-impl:0.13.0'
    runtimeOnly 'io.jsonwebtoken:jjwt-jackson:0.13.0'
    runtimeOnly 'com.mysql:mysql-connector-j'
    runtimeOnly 'org.flywaydb:flyway-mysql'

    testImplementation 'org.springframework.boot:spring-boot-starter-webmvc-test'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

tasks.named('test') {
    useJUnitPlatform()
}

package org.example.board.auth;

import org.example.board.common.ApiException;
import org.example.board.common.ErrorCode;
import org.example.board.user.User;
import org.example.board.user.UserMapper;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AuthService {

    // 없는 이메일과 틀린 비밀번호를 같은 문구로 — 어느 이메일이 가입돼 있는지 흘리지 않는다
    private static final String LOGIN_FAILED = "이메일 또는 비밀번호가 올바르지 않습니다.";

    private final UserMapper userMapper;
    private final PasswordEncoder passwordEncoder;
    private final JwtProvider jwtProvider;

    public AuthService(UserMapper userMapper, PasswordEncoder passwordEncoder, JwtProvider jwtProvider) {
        this.userMapper = userMapper;
        this.passwordEncoder = passwordEncoder;
        this.jwtProvider = jwtProvider;
    }

    @Transactional(readOnly = true)
    public TokenResponse login(LoginRequest request) {
        User user = userMapper.findByEmail(request.email());
        if (user == null) throw new ApiException(ErrorCode.UNAUTHORIZED, LOGIN_FAILED);
        if (!passwordEncoder.matches(request.password(), user.getPasswordHash())) {
            throw new ApiException(ErrorCode.UNAUTHORIZED, LOGIN_FAILED);
        }
        return new TokenResponse(jwtProvider.issue(user.getId()), jwtProvider.validitySeconds());
    }
}

package org.example.board.comment;

import java.time.LocalDateTime;
import java.util.List;

import com.fasterxml.jackson.annotation.JsonInclude;
import org.example.board.post.AuthorResponse;

// 최상위 댓글은 replies(답글 목록)를 가진다. 답글에는 replies가 없다
public record CommentResponse(
        Long id,
        String content,
        AuthorResponse author,
        boolean deleted,
        LocalDateTime createdAt,
        @JsonInclude(JsonInclude.Include.NON_NULL) List<CommentResponse> replies) {

    static final String DELETED_CONTENT = "삭제된 댓글입니다";

    static CommentResponse reply(CommentRow c) {
        return new CommentResponse(c.id, c.content, new AuthorResponse(c.authorId, c.authorNickname), false,
                c.createdAt, null);
    }

    static CommentResponse top(CommentRow c, List<CommentResponse> replies) {
        if (c.deletedAt != null) {
            // 지운 부모는 내용·작성자를 숨기고 자리만 남긴다(답글이 고아가 되지 않게)
            return new CommentResponse(c.id, DELETED_CONTENT, null, true, c.createdAt, replies);
        }
        return new CommentResponse(c.id, c.content, new AuthorResponse(c.authorId, c.authorNickname), false,
                c.createdAt, replies);
    }
}

package org.example.board.comment;

import java.time.LocalDateTime;

// 댓글·작성자 JOIN의 한 행. parentId로 메모리에서 답글을 묶는다.
public class CommentRow {
    public Long id;
    public Long parentId;
    public String content;
    public Long authorId;
    public String authorNickname;
    public LocalDateTime createdAt;
    public LocalDateTime deletedAt;
}

package org.example.board.comment;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

// 평평한 댓글 목록(시간순) → 최상위 + replies 트리
public final class CommentTree {

    private CommentTree() {
    }

    public static List<CommentResponse> build(List<CommentRow> flat) {
        Map<Long, List<CommentResponse>> repliesByParent = new LinkedHashMap<>();
        for (CommentRow c : flat) {
            if (c.parentId != null && c.deletedAt == null) {
                repliesByParent.computeIfAbsent(c.parentId, k -> new ArrayList<>()).add(CommentResponse.reply(c));
            }
        }
        List<CommentResponse> result = new ArrayList<>();
        for (CommentRow c : flat) {
            if (c.parentId != null) {
                continue;
            }
            List<CommentResponse> replies = repliesByParent.getOrDefault(c.id, List.of());
            // 지운 댓글에 살아 있는 답글이 없으면 자리도 남기지 않는다
            if (c.deletedAt != null && replies.isEmpty()) {
                continue;
            }
            result.add(CommentResponse.top(c, replies));
        }
        return result;
    }
}

package org.example.board.post;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.LinkedHashSet;
import java.util.Set;

import org.example.board.user.User;

public class Post {

    private Long id;

    private User author;

    private String title;

    private String content;

    private Visibility visibility;

    private int viewCount;

    private int likeCount;

    // MyBatis 경로에서는 Service가 post_tags INSERT를 명시적으로 수행한다.
    private Set<Tag> tags = new LinkedHashSet<>();

    private LocalDateTime createdAt;

    private LocalDateTime updatedAt;

    private LocalDateTime deletedAt;

    public Post() {
    }

    public Post(User author, String title, String content, Visibility visibility, Set<Tag> tags) {
        this.author = author;
        this.title = title;
        this.content = content;
        this.visibility = visibility;
        this.tags.addAll(tags);
        this.createdAt = now();
        this.updatedAt = this.createdAt;
    }

    private static LocalDateTime now() {
        return LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS);
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public User getAuthor() {
        return author;
    }

    public String getTitle() {
        return title;
    }

    public String getContent() {
        return content;
    }

    public Visibility getVisibility() {
        return visibility;
    }

    public int getViewCount() {
        return viewCount;
    }

    public int getLikeCount() {
        return likeCount;
    }

    public Set<Tag> getTags() {
        return tags;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }

    public LocalDateTime getDeletedAt() {
        return deletedAt;
    }
}

package org.example.board.post;

import java.time.LocalDateTime;

// 글·작성자·태그 LEFT JOIN 결과의 평평한 한 행. 태그 하나마다 글 필드가 반복된다.
