package org.example.board.post;

import java.util.List;

import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.example.board.comment.CommentRow;

@Mapper
public interface PostMapper {
    void insertPost(Post post);
    Tag findTagByName(String name);
    void insertTag(Tag tag);
    void linkTag(@Param("postId") Long postId, @Param("tagId") Long tagId);

    List<PostDetailRow> findDetailRows(Long postId);
    int increaseViewCount(Long postId);
    long countLike(@Param("postId") Long postId, @Param("userId") Long userId);
    List<CommentRow> findCommentRows(Long postId);
